        return np.pi**2.5*KAB*KCD*(-P*PQy*t0**(-3.5)*t4*Boys(3, t1) - PQy*t13*t6 + t10*t12 + t10*t9 + t11*t12 + t11*t9 - t2*t4*t5 + t3 + t7 - t0**(-0.5)*t13*t5*Boys(0, t1)/(P**2*Q**3))
