        return np.pi**2.5*KAB*KCD*(2*ABz*CDy*PQy*alpha*gamma*t11*t7*t8*t9 + 2*ABz*alpha*t0*t2*t4*t5 + ABz*alpha*t11*t16*t17*t18 + 2*CDy*PQy*PQz*delta*t0*t2*t4 - 2*P*PQz*t1**(-3.5)*t5*Boys(3, t3) + 2*PQz*delta*gamma*t11*t19*t7*t8*t9 + PQz*t0*t2*t4 - 2*delta*t13*t15 - t10*t6 - t13 - t14*t15*t2*t4*t6 - delta*t12*t14*t16*t17*t18*t19/Q**3)
