        return np.pi**2.5*KAB*KCD*(2*ABz*CDz*PQx*alpha*gamma*t10*t7*t8*t9 + 2*ABz*PQx*PQz*alpha*t0*t2*t4 + 2*CDx*CDz*PQz*delta*gamma*t10*t7*t8*t9 + 2*CDx*delta*t0*t2*t4*t5 - 2*P*PQx*t1**(-3.5)*t5*Boys(3, t3) - PQx*t0*t12*t13*t2*t4 + PQx*t0*t2*t4 - t11*t12*t14 - t11 - 2*t1**(-0.5)*t13*t14*t6*Boys(0, t3)/(P**2*Q**3))
